package me.eiakoji.eip.endpoints;

import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;

/**
 * Production Idempotent Receiver with Atomic Deduplication and Fencing Token Enforcement.
 */
public final class IdempotentReceiverGateway<T> {

    public record InboundMessage<T>(
        UUID messageId,
        String aggregateId,
        long fencingToken,
        T payload,
        Instant emittedAt
    ) {}

    public enum ProcessingResult {
        EXECUTED,
        DUPLICATE_IGNORED,
        STALE_FENCE_DROPPED
    }

    public interface DeduplicationStore {
        boolean tryAcquire(UUID messageId);
        long getCurrentFencingToken(String aggregateId);
        void updateFencingToken(String aggregateId, long newToken);
    }

    public static final class InMemoryDeduplicationStore implements DeduplicationStore {
        private final Set<UUID> processedIds = ConcurrentHashMap.newKeySet();
        private final Map<String, Long> fencingTokens = new ConcurrentHashMap<>();

        @Override
        public synchronized boolean tryAcquire(UUID messageId) {
            return processedIds.add(messageId);
        }

        @Override
        public synchronized long getCurrentFencingToken(String aggregateId) {
            return fencingTokens.getOrDefault(aggregateId, 0L);
        }

        @Override
        public synchronized void updateFencingToken(String aggregateId, long newToken) {
            fencingTokens.put(aggregateId, newToken);
        }
    }

    private final DeduplicationStore dedupStore;
    private final Consumer<InboundMessage<T>> businessHandler;

    public IdempotentReceiverGateway(
        DeduplicationStore dedupStore,
        Consumer<InboundMessage<T>> businessHandler
    ) {
        this.dedupStore = Objects.requireNonNull(dedupStore);
        this.businessHandler = Objects.requireNonNull(businessHandler);
    }

    public ProcessingResult onMessage(InboundMessage<T> msg) {
        // Step 1: Atomic Deduplication Gate
        if (!dedupStore.tryAcquire(msg.messageId())) {
            // Already processed -> ACK and discard duplicate
            return ProcessingResult.DUPLICATE_IGNORED;
        }

        // Step 2: Fencing Token Validation (v_fence > v_current)
        long currentToken = dedupStore.getCurrentFencingToken(msg.aggregateId());
        if (msg.fencingToken() <= currentToken) {
            // Stale out-of-order message -> drop to prevent state regression
            return ProcessingResult.STALE_FENCE_DROPPED;
        }

        // Step 3: Execute Business Logic within Transaction Boundary
        businessHandler.accept(msg);
        dedupStore.updateFencingToken(msg.aggregateId(), msg.fencingToken());

        return ProcessingResult.EXECUTED;
    }
}
